def apply_transf(transf, cells):
    """Apply transformation to each cell, return new set of cells"""
    result = set()
    for sr, sc in cells:
        new_pos = transf(sr, sc)
        # Apply diag rays from new_pos going up toward row 0
        # But filter by some condition later
        for k in range(1, H-sr):
            nr, nc = new_pos[0]-k, new_pos[1]+k  # up-right direction
            if 0 <= nr < H and 0 <= nc < W:
                result.add((nr, nc))
        for k in range(1, max(sc+1, H-sr)):
            nr, nc = new_pos[0]-k, new_pos[1]-k  # up-left direction
            if 0 <= nr < H and 0 <= nc < W:
                result.add((nr, nc))

    return result

# Define transformation functions
def id_t(r, c): return (r, c)

def horiz_reflect(r, c): return (r, 5-c)

def vert_reflect(r, c): return (5-r, c)

def diag_bounce(r, c):
    """Bounce off left wall - reflect column"""
    return (c, r)  # swap coords

def vertical_diag_transform(r, c):
    """Transform position vertically along diagonal to center col"""
    # Move column toward center (2.5)
    if c < 2:
        target_c = 1 + (c % 2)  # rounds to 1 or 2
    else:
        target_c = 3 - ((c - 3) % 2)  # rounds to 3 or 4
    return (r, target_c)

